 26	/// Themed settings surface for the Void chrome.
 27	///
 28	/// The single settings UI for the app. App-wide groups come first
 29	/// (MODE / LOOK / LIBRARY / EXTERNAL), then the screen-specific cluster
 30	/// (SOUND / DISPLAY) so the two never interleave, with ABOUT as the footer.
 31	/// Groups adapt to the active operating mode and active home-screen so
 32	/// per-visualisation knobs only appear when relevant. A pinned status strip
 33	/// (queue size + shuffle toggle) sits between the header and the MODE group
 34	/// when the queue is non-empty.
 35	///
 36	/// Rows are data-driven: each is a [_Cycle], [_Toggle] or [_Slider] spec that a
 37	/// single builder renders. The active [AppPalette] / [AppTypography] /
 38	/// [AppGeometry] are captured by the row builders so specs stay declarative.
 39	class VoidSettingsSheet extends HookWidget {
 40	  const VoidSettingsSheet({super.key});
 41	
 42	  static Future<void> push(BuildContext context) => Navigator.of(context).push(
 43	        MaterialPageRoute<void>(builder: (_) => const VoidSettingsSheet()),
 44	      );
 45	
 46	  /// Next value in [values] after [cur], wrapping around.
 47	  static T _next<T>(List<T> values, T cur) =>
 48	      values[(values.indexOf(cur) + 1) % values.length];
 49	
 50	  @override
 51	  Widget build(BuildContext context) {
 52	    final settings = SettingsService();
 53	
 54	    // Mutating any watched notifier rebuilds the whole sheet, so cycle/slider
 55	    // handlers never need an explicit setState.
 56	    useListenable(Listenable.merge(<Listenable>[
 57	      settings.operatingModeNotifier,
 58	      settings.themeIdNotifier,
 59	      settings.themeVariantNotifier,
 60	      settings.screenConfigNotifier,
 61	      settings.immersiveNotifier,
 62	      settings.transportPositionNotifier,
 63	      settings.browserPresentationNotifier,
 64	      settings.fullScreenNotifier,
 65	      settings.uiScaleNotifier,
 66	      settings.settingsNotifier,
 67	      settings.useFilenameForMetadataNotifier,
 68	      settings.smartFoldersPresentationNotifier,
 69	      settings.debugLayoutNotifier,
 70	    ]));
 71	
 72	    final versionLabel = useState('...');
 73	    final hasNotification = useState(false);
 74	    final hasAudio = useState(false);
 75	
 76	    useEffect(() {
 77	      var active = true;
 78	      () async {
 79	        try {
 80	          final info = await PackageInfo.fromPlatform();
 81	          if (active) versionLabel.value = '${info.version}+${info.buildNumber}';
 82	        } catch (_) {
 83	          // Non-fatal — keep the placeholder.
 84	        }
 85	      }();
 86	      return () => active = false;
 87	    }, const []);
 88	
 89	    // Permission probe — re-runnable from external-settings rows.
 90	    final refreshPermissions = useCallback(() async {
 91	      if (!PlatformChannels.isAndroid) return;
 92	      final p = PlatformChannels();
 93	      hasNotification.value = await p.isNotificationAccessGranted();
 94	      hasAudio.value = await p.hasAudioPermission();
 95	    }, const []);
 96	
 97	    useEffect(() {
 98	      refreshPermissions();
 99	      return null;
100	    }, const []);
101	
102	    final theme = Theme.of(context);
103	    final p = theme.extension<AppPalette>()!;
104	    final t = theme.extension<AppTypography>()!;
105	    final g = theme.extension<AppGeometry>()!;
106	
107	    // -------------------------------------------------------------------------
108	    // Row handlers (side effects only — notifiers drive the rebuild).
109	    // -------------------------------------------------------------------------
110	    void cycleScreen() {
111	      const order = [
112	        ScreenType.spectrum,
113	        ScreenType.polo,
114	        ScreenType.dot,
115	        ScreenType.void_,
116	        ScreenType.cassette,
117	      ];
118	      settings.saveScreenConfig(
119	          switch (_next(order, settings.screenConfigNotifier.value.type)) {
120	        ScreenType.spectrum => const SpectrumScreenConfig(),
121	        ScreenType.polo => const PoloScreenConfig(),
122	        ScreenType.dot => const DotScreenConfig(),
123	        ScreenType.void_ => const VoidScreenConfig(),
124	        ScreenType.cassette => const CassetteScreenConfig(),
125	      });
126	    }
127	
128	    void cycleSpectrum<T>(
129	        List<T> values, T cur, SpectrumScreenConfig Function(T) build) {
130	      if (settings.screenConfigNotifier.value is! SpectrumScreenConfig) return;
131	      settings.saveScreenConfig(build(_next(values, cur)));
132	    }
133	
134	    String uiScaleLabel() {
135	      final v = settings.uiScaleNotifier.value;
136	      return v < 0 ? 'auto' : '${v.toStringAsFixed(2)}x';
137	    }
138	
139	    String labelFor(ScreenType type) => switch (type) {
140	          ScreenType.spectrum => 'spectrum',
141	          ScreenType.polo => 'polo',
142	          ScreenType.dot => 'dot',
143	          ScreenType.void_ => 'void',
144	          ScreenType.cassette => 'cassette',
145	        };
146	
147	    Future<void> openNotificationSettings() async {
148	      await PlatformChannels().openNotificationSettings();
149	      await Future<void>.delayed(const Duration(milliseconds: 400));
150	      await refreshPermissions();
151	    }
152	
153	    Future<void> requestMicPermission() async {
154	      await Permission.microphone.request();
155	      await refreshPermissions();
156	    }
157	
158	    double effectiveAutoUiScale() {
159	      final dpr = View.of(context).devicePixelRatio;
160	      if (dpr <= 0) return 1.0;
161	      final logicalWidth = MediaQuery.of(context).size.width;
162	      if (logicalWidth <= 0) return 1.0;
163	      return settings.calculateSmartScaleForWidth(logicalWidth,
164	          devicePixelRatio: dpr);
165	    }
166	
167	    // -------------------------------------------------------------------------
168	    // Visual primitives.
169	    // -------------------------------------------------------------------------
170	    TextStyle rowStyle(Color color) =>
171	        TextStyle(color: color, fontFamily: t.monoFamily, fontSize: t.rowSize);
172	
173	    final rowBorder = BoxDecoration(
174	      border: Border(
175	          bottom: BorderSide(color: p.divider, width: g.dividerThickness)),
176	    );
177	
178	    Widget autoChip({required bool isAuto}) => PressFeedback(
179	          onTap: () => settings.saveUiScale(-1.0),
